import app from 'flarum/admin/app';
export const EXT = 'ernestdefoe-permission-desk';
export const ADMIN = 1;
export const GUEST = 2;
export const MEMBER = 3;
export const t = (key, params = {}) => app.translator.trans(`${EXT}.admin.${key}`, params);
export function api(method, path, body, quiet = false) {
  return app.request({
    method,
    url: `${app.forum.attribute('apiUrl')}/permission-desk${path}`,
    body,
    ...(quiet ? {
      errorHandler: e => {
        throw e;
      }
    } : {})
  });
}
const norm = ids => Array.from(new Set(ids.map(Number))).filter(id => id !== ADMIN).sort((a, b) => a - b);
const same = (a, b) => a.length === b.length && a.every((x, i) => x === b[i]);
/**
 * Lives as long as the admin page: staged changes survive switching tabs and pages, and are only
 * written when the admin saves them from the review.
 */
export const desk = {
  staged: {},
  context: {
    kind: 'save'
  },
  historyVersion: 0,
  /** What is saved now (core's own app.data.permissions, kept current after every save). */
  base(key) {
    return norm(app.data.permissions[key] || []);
  },
  cur(key) {
    return this.staged[key] ?? this.base(key);
  },
  stage(key, ids) {
    const next = norm(ids);
    if (same(next, this.base(key))) delete this.staged[key];else this.staged[key] = next;
  },
  discard() {
    this.staged = {};
    this.context = {
      kind: 'save'
    };
  },
  diff() {
    const out = [];
    Object.keys(this.staged).sort().forEach(key => {
      const before = this.base(key);
      const after = this.staged[key];
      after.filter(g => !before.includes(g)).forEach(group => out.push({
        key,
        group,
        op: '+'
      }));
      before.filter(g => !after.includes(g)).forEach(group => out.push({
        key,
        group,
        op: '-'
      }));
    });
    return out;
  },
  /** Replace core's permission map with the server's (after a save or a conflict). */
  setMap(map) {
    const next = {};
    Object.keys(map).forEach(key => next[key] = map[key].map(String));
    app.data.permissions = next;
    Object.keys(this.staged).forEach(key => this.stage(key, this.staged[key]));
  },
  setOne(key, ids) {
    if (ids.length) app.data.permissions[key] = ids.map(String);else delete app.data.permissions[key];
  }
};
/**
 * How a group stands on a permission: Admins always (locked); its own grant; inherited because
 * Everyone or Members have it (switching it off for this group would change nothing); or off.
 */
export function rowState(group, key) {
  const set = desk.cur(key);
  if (group === ADMIN) return {
    st: 'lock',
    via: null
  };
  if (set.includes(group)) return {
    st: 'on',
    via: group !== GUEST && set.includes(GUEST) ? GUEST : group > MEMBER && set.includes(MEMBER) ? MEMBER : null
  };
  if (group !== GUEST && set.includes(GUEST)) return {
    st: 'inh',
    via: GUEST
  };
  if (group > MEMBER && set.includes(MEMBER)) return {
    st: 'inh',
    via: MEMBER
  };
  return {
    st: 'off',
    via: null
  };
}
export const allowed = (group, key) => rowState(group, key).st !== 'off';
export const scoped = (key, scope) => scope === 'global' ? key : `tag${scope}.${key}`;
export function splitKey(key) {
  const m = key.match(/^tag(\d+)\.(.+)$/);
  return m ? {
    tag: m[1],
    key: m[2]
  } : {
    tag: null,
    key
  };
}
export function required(key) {
  return app.getRequiredPermissions(key);
}